{"_id":"6ac6033b787dd75562cd1f19","id":"e2rea1/RouteWeaver-4B","private":false,"pipeline_tag":"text-generation","library_name":"transformers","tags":["transformers","safetensors","qwen3","text-generation","llm-routing","reinforcement-learning","agent","verl","conversational","base_model:Qwen/Qwen3-4B-Instruct-2507","base_model:finetune:Qwen/Qwen3-4B-Instruct-2507","license:apache-2.0","text-generation-inference","endpoints_compatible","region:us"],"downloads":90,"likes":1,"modelId":"e2rea1/RouteWeaver-4B","author":"e2rea1","sha":"d5752e7522e638946f0f6c69783459db1e940cea","lastModified":"2026-10-09T07:20:45.000Z","gated":false,"disabled":false,"widgetData":[{"text":"Hi, what can you help me with?"},{"text":"What is 84 * 3 / 2?"},{"text":"Tell me an interesting fact about the universe!"},{"text":"Explain quantum computing in simple terms."}],"model-index":null,"config":{"architectures":["Qwen3ForCausalLM"],"model_type":"qwen3","tokenizer_config":{"bos_token":null,"eos_token":"<|im_end|>","pad_token":"<|endoftext|>","unk_token":null},"chat_template_jinja":"{%- if tools %}
    {{- '<|im_start|>system\n' }}
    {%- if messages[0].role == 'system' %}
        {{- messages[0].content + '\n\n' }}
    {%- endif %}
    {{- "# Tools\n\nYou may call one or more functions to assist with the user query.\n\nYou are provided with function signatures within <tools></tools> XML tags:\n<tools>" }}
    {%- for tool in tools %}
        {{- "\n" }}
        {{- tool | tojson }}
    {%- endfor %}
    {{- "\n</tools>\n\nFor each function call, return a json object with function name and arguments within <tool_call></tool_call> XML tags:\n<tool_call>\n{\"name\": <function-name>, \"arguments\": <args-json-object>}\n</tool_call><|im_end|>\n" }}
{%- else %}
    {%- if messages[0].role == 'system' %}
        {{- '<|im_start|>system\n' + messages[0].content + '<|im_end|>\n' }}
    {%- endif %}
{%- endif %}
{%- for message in messages %}
    {%- if message.content is string %}
        {%- set content = message.content %}
    {%- else %}
        {%- set content = '' %}
    {%- endif %}
    {%- if (message.role == "user") or (message.role == "system" and not loop.first) %}
        {{- '<|im_start|>' + message.role + '\n' + content + '<|im_end|>' + '\n' }}
    {%- elif message.role == "assistant" %}
        {{- '<|im_start|>' + message.role + '\n' + content }}
        {%- if message.tool_calls %}
            {%- for tool_call in message.tool_calls %}
                {%- if (loop.first and content) or (not loop.first) %}
                    {{- '\n' }}
                {%- endif %}
                {%- if tool_call.function %}
                    {%- set tool_call = tool_call.function %}
                {%- endif %}
                {{- '<tool_call>\n{"name": "' }}
                {{- tool_call.name }}
                {{- '", "arguments": ' }}
                {%- if tool_call.arguments is string %}
                    {{- tool_call.arguments }}
                {%- else %}
                    {{- tool_call.arguments | tojson }}
                {%- endif %}
                {{- '}\n</tool_call>' }}
            {%- endfor %}
        {%- endif %}
        {{- '<|im_end|>\n' }}
    {%- elif message.role == "tool" %}
        {%- if loop.first or (messages[loop.index0 - 1].role != "tool") %}
            {{- '<|im_start|>user' }}
        {%- endif %}
        {{- '\n<tool_response>\n' }}
        {{- content }}
        {{- '\n</tool_response>' }}
        {%- if loop.last or (messages[loop.index0 + 1].role != "tool") %}
            {{- '<|im_end|>\n' }}
        {%- endif %}
    {%- endif %}
{%- endfor %}
{%- if add_generation_prompt %}
    {{- '<|im_start|>assistant\n' }}
{%- endif %}"},"cardData":{"license":"apache-2.0","base_model":"Qwen/Qwen3-4B-Instruct-2507","library_name":"transformers","pipeline_tag":"text-generation","tags":["llm-routing","reinforcement-learning","agent","verl"]},"transformersInfo":{"auto_model":"AutoModelForCausalLM","pipeline_tag":"text-generation","processor":"AutoTokenizer"},"siblings":[{"rfilename":".gitattributes","blobId":"52373fe24473b1aa44333d318f578ae6bf04b49b","size":1570},{"rfilename":"README.md","blobId":"115c18aff6fbdffa096f4f1ccef0203b54f586a4","size":5023},{"rfilename":"added_tokens.json","blobId":"b54f9135e44c1e81047e8d05cb027af8bc039eed","size":707},{"rfilename":"chat_template.jinja","blobId":"70adff8a08fb31e0636f618564838d4bf3c05286","size":2630},{"rfilename":"config.json","blobId":"4c88a6d0a0ab5166596b10c9061a36af1e65f82d","size":1536},{"rfilename":"generation_config.json","blobId":"9e79c529e48f4086ed36490eac3e668fa4b2ba84","size":213},{"rfilename":"merges.txt","blobId":"31349551d90c7606f325fe0f11bbb8bd5fa0d7c7","size":1671853},{"rfilename":"model.safetensors","blobId":"5d2274091c7afb055818167e0c6c339f9d5da323","size":8822894520,"lfs":{"sha256":"f85fd78f191e9399159b5c9df80b8239445b8deca01d38d05973e492adbf6c99","size":8822894520,"pointerSize":135}},{"rfilename":"special_tokens_map.json","blobId":"ac23c0aaa2434523c494330aeb79c58395378103","size":613},{"rfilename":"tokenizer.json","blobId":"cd71f61a15a522601badb3dc960d800d9cb3766c","size":11422654,"lfs":{"sha256":"aeb13307a71acd8fe81861d94ad54ab689df773318809eed3cbe794b4492dae4","size":11422654,"pointerSize":133}},{"rfilename":"tokenizer_config.json","blobId":"c9fc12215bad2b9d91ad3289720ddf9839515072","size":5405},{"rfilename":"vocab.json","blobId":"4783fe10ac3adce15ac8f358ef5462739852c569","size":2776833}],"spaces":[],"createdAt":"2026-10-07T08:30:51.000Z","safetensors":{"parameters":{"BF16":4411424256},"total":4411424256},"usedStorage":8834317174}
